  ('aa-50-armored-artillery-troop-carrier', 'Multi-Missile and Laser Turret (1)', 500, NULL, 4),
  ('aa-50-armored-artillery-troop-carrier', 'Medium-Range Missile Launcher (1, rear)', 120, NULL, 5),
  ('aa-50-armored-artillery-troop-carrier', 'Short-Range Missile Launcher (1, rear)', 150, NULL, 6),
