INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('xml-280-black-eagle', 1, 'Nose Lasers (3)', '3D6 M.D. single blast, 6D6 double blast, 1D4x10+8 M.D. triple blast', 1, '4,000 feet (1,219 m)', 'Each single, dual or triple blast at one target counts as one of the pilot''s melee attacks', 'Effectively unlimited', NULL, 'Fixed forward, recessed; anti-aircraft/anti-Gargoyle.'),
  ('xml-280-black-eagle', 2, 'Nose Mini-Missile Launchers (2)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', '1, 2 or 4', 'Eight total, four per launcher', NULL, 'Recessed in each side of the nose.'),
  ('xml-280-black-eagle', 3, 'Wing Hardpoints (4)', 'Varies with type of weapon used', 1, 'Varies with type of weapon used', 'Varies with type of weapon used', 'Varies with type of weapon used', NULL, 'Two per wing; mount any XLH series weapon pod.'),
  ('xml-280-black-eagle', 4, 'Anti-Missile Chaff Dispenser (1)', 'None; roll percentile: 01-50% the missile or volley detonates in the chaff, 51-75% it loses its target and veers off (may lock onto a nearby aircraft), 76-00% no effect', 0, NULL, NULL, 'Four', NULL, 'Any Gargoyle or other flier that passes through the cloud suffers half speed, half attacks and half combat bonuses for 1D4 melee rounds.'),
  ('xml-283-wraith', 1, 'Wing Lasers (4)', '3D6 M.D. single blast, 6D6 double, 1D4x10+8 M.D. triple, 1D6x10+6 quadruple blast', 1, '4,000 feet (1,219 m)', 'Each single, dual, triple or quadruple blast at one target counts as one of the pilot''s melee attacks', 'Effectively unlimited', NULL, 'Forward fixed; two sit under the wings close to the nose and two on the upper wing surfaces close to the thrusters.'),
  ('xml-283-wraith', 2, 'Belly Mini-Missile Launcher (1)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', '1, 2 or 4', 'Six total', NULL, 'Missiles drop from a housing through a belly door and then fly to the target.'),
  ('xml-285-ghost', 1, 'Forward Pulse Lasers (4)', '3D6 M.D. single blast, 6D6 double, 1D4x10+8 M.D. triple, 1D6x10+6 quadruple blast', 1, '4,000 feet (1,219 m)', 'Each single, dual, triple or quadruple blast at one target counts as one of the pilot''s melee attacks', 'Effectively unlimited', NULL, 'Concealed in the nose and powered by the nuclear plant.'),
  ('xml-285-ghost', 2, 'Ventral Internal Weapons Bay #1, Mini-Missiles', 'Varies with medium-range missile; heavy high-explosive (standard issue) 3D6x10 M.D. to everything in a 30 foot (9.1 m) radius', 1, 'Varies with medium-range missile, usually 40-60 miles (64-96 km); HE 40 miles (64 km)', 'One at a time or volleys of 2, 4, 8, 12 or all 16', '16 missiles', '+3 to strike from the missile guidance; laser designators override it with their own bonus', 'Printed heading says mini-missiles but the bay carries medium-range missiles; stored as printed.'),
  ('xml-285-ghost', 3, 'Internal Weapons Bays #2 & 3: Mini-Missile Launcher', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', '1, 2, 4 or 6 at a time', '16 total mini-missiles', NULL, 'Side bays on the outer intake walls hold bombs, mini-missiles or drop deployment pods; usually one of each.'),
  ('xml-285-ghost', 4, 'Internal Weapons Bays #2 & 3: Free Fall or Gravity Bombs', 'Varies with bomb type; as medium-range missiles of the same type, with double the blast radius', 1, 'Dropped from the air onto a ground target', 'Clusters of 2, 4 or 8', '8 bombs per bay', NULL, NULL),
  ('xml-285-ghost', 5, 'Wing Hardpoints (4)', 'Varies with type of weapon used', 1, 'Varies with type of weapon used', 'Varies with type of weapon used', 'Varies with type of weapon used', NULL, 'Two per wing, close to the body; mount any XLH series weapon pod.'),
  ('xml-285-ghost', 6, 'Anti-Missile Chaff Dispenser (1)', 'None; roll percentile: 01-50% the missile or volley detonates in the chaff, 51-75% it loses its target and veers off (may lock onto a nearby aircraft), 76-00% no effect', 0, NULL, NULL, 'Four', NULL, 'Any Gargoyle or other flier that passes through the cloud suffers half speed, half attacks and half combat bonuses for 1D4 melee rounds.'),
  ('xmf-1-drop-fort', 1, 'Short-Range Missile Launcher (1)', 'Varies with missile; typically high-explosive 2D6x10 M.D. to everything in a 15 foot (4.6 m) radius, or fragmentation 2D4x10 M.D. in a 20 foot (6.1 m) radius', 1, 'Varies with missile; high-explosive five miles (8 km), fragmentation three miles (4.8 km)', 'One at a time or volleys of 2 or 4', 'Four missiles, plus two reloads; robot or power armor required to reload by hand', NULL, 'Side of the roof; rotates 360 degrees.'),
  ('xmf-1-drop-fort', 2, 'Mini-Missile Launchers (2)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or volleys of 2, 4 or 6', '24 total, 12 per launcher, plus one reload each (24 more)', NULL, 'Drop down out of the ceiling once the roof is up; one points to the front, the other to the rear; each rotates 180 degrees with a 20 degree arc.'),
  ('xmf-1-drop-fort', 3, 'Optional Weapon Turret (1)', '5D6 M.D. per single blast', 1, '4,000 feet (1,219 m)', 'Single shots only; each blast counts as one melee attack of the dedicated gunner', 'Effectively unlimited', NULL, 'Usually a laser, on the roof opposite the missile launcher.'),
  ('ngr-undertow-submersible-carrier', 1, 'Medium-Range Missile Launchers (5)', '5D6x10 M.D. for medium multi-warhead missiles', 1, '80 miles (128 km)', 'One at a time or volleys of 2, 3, 4 or all five', '432 in launch system, with an additional 216 in storage', '+1 to strike and +1 initiative from the targeting computer', 'Silo-style, in a ring around the upper third, facing up; anti-ship and anti-aircraft.'),
  ('ngr-undertow-submersible-carrier', 2, 'Long-Range Missile Launchers (5)', '4D6x10 M.D. high-explosive (heavy), 1D4x100 M.D. nuclear (medium) or 2D4x100 M.D. nuclear multi-warhead', 1, '500 miles (800 km) for high-explosive, 1,000-1,800 miles (1,600-2,880 km) for nuclear', 'One at a time or volleys of 2, 3, 4 or all five', '432 in launch system, with an additional 216 in storage', '+1 to strike and +1 initiative from the targeting computer', 'Alternating ring about 150 feet (45.7 m) above the medium-range launchers; tactical ground-based strikes and anti-fortification.'),
  ('tx-misb-mobile-infantry-strike-base', 1, 'Forward Section: Main Super-Particle Beam Acceleration Cannon (1)', '3D6x100 M.D. per full powered blast; Critical Strike adds 1D8x100 M.D. on an unmodified 19 or 20', 1, '12,000 feet (3657.6 m)', 'Once per melee round (about 10 seconds to recycle)', 'Effectively unlimited', '+3 to strike (independent coordinated targeting)', 'After 10 shots it must cool five minutes; each further shot has a 01-50% chance of system failure, and a failed gun cannot fire for 1D4 melee rounds. Points forward, 90 degree up/down arc, dedicated gunner.'),
  ('tx-misb-mobile-infantry-strike-base', 2, 'Forward Section: Super-Laser Cannon (1)', '1D6x10 M.D. per single blast or 4D4x10 M.D. per triple pulse blast', 1, '10,000 feet (3,048 m)', 'Each shot counts as one of the gunner''s melee attacks', 'Effectively unlimited', '+3 to strike (coordinated targeting)', 'Right of the main gun; can be fire-linked with the Super-Ion Cannon.'),
  ('tx-misb-mobile-infantry-strike-base', 3, 'Forward Section: Super-Ion Cannon (1)', '2D6x10 M.D. per single blast', 1, '6,000 feet (1829 m)', 'Single shot only; each blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', '+3 to strike (coordinated targeting)', 'Left of the main gun.'),
  ('tx-misb-mobile-infantry-strike-base', 4, 'Forward Section: Long-Range Missile Launcher (2)', 'Varies; standard issue 12 heavy high-explosive (4D6x10 M.D. to everything in a 40 foot/12.2 m radius), 2 plasma (5D6x10 M.D., 50 foot/15.2 m radius) and 2 nuclear (heavy, 1D6x100 M.D., 50 foot/15.2 m radius)', 1, 'Varies; heavy high-explosive and plasma 500 miles (800 km), nuclear (heavy) 1,000 miles (1,600 km)', 'One at a time or in volleys of 2, 4 or 6', '96, 48 missiles per launcher', NULL, 'The range line gives the mix as 12 HE, 4 plasma and 4 nuclear, the damage line as 12, 2 and 2; stored as printed. Raises and turns forward to fire, reloads automatically when stowed.'),
  ('tx-misb-mobile-infantry-strike-base', 5, 'Forward Section: Forward Double-Barreled Laser Turrets (2)', '5D6 M.D. per single blast or 1D6x10 M.D. per dual blast', 1, '4,000 feet (1,219 m)', 'Each single or dual blast counts as one of the gunner''s attacks per melee round', 'Effectively unlimited', NULL, 'Each has its own gunner; 220 degree arc, 90 degrees up and down.'),
  ('tx-misb-mobile-infantry-strike-base', 6, 'Forward Section: Forward Ion Tube Cannons (2)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per dual simultaneous blast', 1, '4,000 feet (1219 m)', 'Each single or dual blast uses one attack', 'Effectively unlimited', NULL, 'Double-barreled, in tubes on each side of the ram prow; 30 degree arc.'),
  ('tx-misb-mobile-infantry-strike-base', 7, 'Forward Section: Concealed Pop-Up Mini-Missile Launchers (6)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or volleys of 2, 4, 6, 8, 10 or 12; each launcher fires up to 12 in one volley', '96 mini-missiles per launcher, 576 total; reloaded automatically when the launcher retracts (one melee round)', NULL, NULL),
  ('tx-misb-mobile-infantry-strike-base', 8, 'Forward Section: Forward Ram Prow', '2D4x10 M.D. at 50 mph (80 km) or more, 1D4x10 M.D. at slower speeds', 1, NULL, NULL, NULL, NULL, '01-90% chance to knock giants and robots under 60 feet (18.3 m) off their feet; victims lose initiative and two melee attacks.'),
  ('tx-misb-mobile-infantry-strike-base', 9, 'Forward Section: Double-Barreled Laser Turrets (6, rear)', '3D6 M.D. per single blast or 6D6 M.D. per simultaneous double blast', 1, '4,000 feet (1219 m)', 'The combat A.I. can fire each turret six times per melee round', 'Effectively unlimited', NULL, 'Only exposed when the forward section detaches; automated by a combat A.I. that recognizes 3,000 enemies.'),
  ('tx-misb-mobile-infantry-strike-base', 10, 'Command Center: Dual Particle Beam Turret (1)', '1D6x10+10 M.D. per single blast or 2D6x10+20 M.D. per simultaneous dual blast; Critical Strike on an unmodified 19 or 20', 1, '2,000 feet (610 m)', 'Each single or dual blast counts as one of the dedicated gunner''s attacks per melee', 'Effectively unlimited', NULL, 'Top of the Command Center; 360 degree rotation, 70 degree arc.'),
  ('tx-misb-mobile-infantry-strike-base', 11, 'Command Center: Double-Barreled Laser Turret (2)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per simultaneous dual blast', 1, '6,000 feet (1,829 m)', 'Each single or dual blast counts as one of the dedicated gunner''s melee attacks', 'Effectively unlimited', NULL, NULL),
  ('tx-misb-mobile-infantry-strike-base', 12, 'Command Center: Side Laser Turrets (4)', '4D6 M.D. per single blast or 1D4x10+8 M.D. per simultaneous double blast', 1, '4,000 feet (1219 m)', 'Each single or dual blast counts as one of the dedicated gunner''s melee attacks', 'Effectively unlimited', NULL, NULL),
  ('tx-misb-mobile-infantry-strike-base', 13, 'Command Center: Multi-System Medium- and Long-Range Missile Launcher (1)', 'Medium-range: typically half high-explosive (3D6x10 M.D., 30 foot/9.1 m radius) and half multi-warhead (5D6x10 M.D., 20 foot/6.1 m radius). Long-range: typically six high-explosive (3D6x10 M.D., 30 foot/9.1 m radius) and two multi-warhead (5D6x10 M.D., 20 foot/6.1 m radius)', 1, 'Medium-range typically 40 miles (64 km); long-range heavy high-explosive 500 miles (800 km), nuclear (heavy) 1,000 miles (1,600 km)', 'One at a time or in volleys of 2, 4 or 6', 'Medium-range missiles: 12 total. Long-range missiles: 8', NULL, 'Side-firing, left side; two gunners and a communications officer. The range text calls the long-range mix high-explosive and nuclear, the damage text high-explosive and multi-warhead; stored as printed.'),
  ('tx-misb-mobile-infantry-strike-base', 14, 'Command Center: Concealed Pop-Up Mini-Missile Launchers (10)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or volleys of 2, 4, 6, 8, 10 or 12; each launcher fires up to 12 in one volley', '96 mini-missiles per launcher, 960 total; reloaded automatically when the launcher retracts (one melee round)', NULL, NULL),
  ('tx-misb-mobile-infantry-strike-base', 15, 'Rear Section: Recoilless Anti-Aircraft Flak Cannon (1)', 'Flak: 5D6 M.D. single round, 1D6x10 M.D. double blast, 2D6x10 M.D. to a 5 foot (1.5 m) radius per six round burst. Mini-missiles: armor piercing 1D4x10 M.D. to a 3 foot (0.9 m) radius', 1, 'Flak cannon 10,000 feet (3,048 m); mini-missiles one mile (1.6 km)', 'Each single shot or burst counts as one melee attack of the gunner', 'Flak cannon 1,600 rounds (266 bursts of six or 800 two round bursts); mini-missiles 96', NULL, 'A pair of flak cannons and a mini-missile launcher in one turret; 360 degrees, 90 degree arc, two gunners and a communications officer.'),
  ('tx-misb-mobile-infantry-strike-base', 16, 'Rear Section: Double-Barreled Laser Turrets (2)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per simultaneous double blast', 1, '6,000 feet (1,829 m)', 'Each single or dual blast counts as one of the dedicated gunner''s melee attacks', 'Effectively unlimited', NULL, NULL),
  ('tx-misb-mobile-infantry-strike-base', 17, 'Rear Section: Single Barrel Laser Turrets (4)', '4D6 M.D. per single blast or 1D4x10+4 M.D. per simultaneous double blast when fire-linked', 1, '4,000 feet (1,219 m)', 'Each single or dual blast counts as one of the dedicated gunner''s melee attacks', 'Effectively unlimited', NULL, NULL),
  ('tx-misb-mobile-infantry-strike-base', 18, 'Rear Section: Concealed Pop-Up Mini-Missile Launchers (6)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or volleys of 2, 4, 6, 8, 10 or 12; each launcher fires up to 12 in one volley', '96 mini-missiles per launcher, 576 total; reloaded automatically when the launcher retracts (one melee round)', NULL, NULL),
  ('tx-misb-ia-30-infantry-apc', 1, 'Double-Barreled Laser Turret (2)', '1D4x10 M.D. per single blast or 2D4x10 M.D. per simultaneous double blast', 1, '4,000 feet (1,219 m)', 'Each single or dual blast uses one attack', 'Effectively unlimited', '+1 to strike', 'Front sides; 360 degrees, 90 degree arc, dedicated gunner each; cannot fire-link.'),
  ('tx-misb-ia-30-infantry-apc', 2, 'Ion Turrets (2)', '4D6 M.D. per single blast or 1D4x10 M.D. per dual simultaneous blast', 1, '2,000 feet (610 m)', 'Each single or dual blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', NULL, 'Rear sides, double-barrel; cannot fire-link.'),
  ('tx-misb-ia-30-infantry-apc', 3, 'Front Mini-Missile Launcher (1)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or in volleys of 2, 4, 6, 10 or all 24', '24 mini-missiles', NULL, 'Box launcher in the nose, fired by the pilot or co-pilot.'),
  ('tx-misb-ia-30-infantry-apc', 4, 'Side Mini-Missile Tube Launchers (2)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or in volleys of 2, 4, 6 or 12', '96 mini-missiles per launcher, for a total of 192', NULL, 'Fired by the pilot or co-pilot.'),
  ('aa-50-armored-artillery-troop-carrier', 1, 'Main Gun (1)', '2D4x10+8 M.D. per single blast; Critical Strike on an unmodified 19 or 20', 1, '4,000 feet (1,219 m)', 'Each shot counts as one melee attack for the dedicated gunner', 'Effectively unlimited', '+1 to strike', 'Particle beam cannon, fixed forward with a 90 degree up/down arc.'),
  ('aa-50-armored-artillery-troop-carrier', 2, 'Laser & Ion Turrets (2)', 'Laser 5D6 M.D. per single blast. Ion 4D6 M.D. per single blast or 1D4x10 M.D. per dual simultaneous blast. 1D6x10+6 M.D. when both ion guns and the laser fire at the same target', 1, 'Laser 4,000 feet (1,219 m); ion 2,000 feet (610 m)', 'Each single, dual or triple simultaneous blast counts as one of the dedicated gunner''s melee attacks', 'Effectively unlimited', '+1 to strike with laser', 'Forward turrets, one laser and two ion cannons each; 360 degrees; cannot fire-link with each other.'),
  ('aa-50-armored-artillery-troop-carrier', 3, 'Ion Turrets (2)', '4D6 M.D. per single blast or 1D4x10 M.D. per dual simultaneous blast', 1, '2,000 feet (610 m)', 'Each single or dual blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', NULL, 'Rear sides, double-barrel; cannot fire-link.'),
  ('aa-50-armored-artillery-troop-carrier', 4, 'Medium-Range Missile Launcher', 'Varies; typically high-explosive 3D6x10 M.D. to a 30 foot (9.1 m) radius or fragmentation 2D6x10 M.D. to a 40 foot (12.2 m) radius', 1, 'Varies with missile, typically 40 miles (64 km)', 'Volleys of 2 or 3; each volley counts as one melee attack', '24 total medium-range missiles', NULL, 'Right side, rear; dedicated gunner.'),
  ('aa-50-armored-artillery-troop-carrier', 5, 'Short-Range Missile Launcher', 'Varies; typically high-explosive 2D6x10 M.D. to a 15 foot (4.6 m) radius or fragmentation 2D4x10 M.D. to a 20 foot (6.1 m) radius', 1, 'Varies; high-explosive five miles (8 km), fragmentation three miles (4.8 km)', 'One at a time or in volleys of 2 or 3', '32 total missiles', NULL, 'Left side, rear; dedicated gunner.'),
  ('aa-50-armored-artillery-troop-carrier', 6, 'Concealed Pop-Up Mini-Missile Launchers (4)', 'Varies with missile; fragmentation (standard issue) 5D6 M.D. to everything in a 20 foot (6.1 m) radius', 1, 'Varies with missile type; a half mile (0.8 km) for standard issue fragmentation', 'One at a time or in volleys of 2, 4 or 6; each launcher fires up to six in one volley', '32 mini-missiles per launcher, 128 total; reloaded automatically when retracted (one melee round)', NULL, NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 9 vessels are in and cite Triax 2' AS assertion, count(*) AS got, 9 AS want
  FROM vehicles WHERE source_book LIKE 'Rifts World Book 31: Triax 2 p.%' AND slug IN ('xml-280-black-eagle', 'xml-283-wraith', 'xml-285-ghost', 'ngr-standard-deployment-pod', 'xmf-1-drop-fort', 'ngr-undertow-submersible-carrier', 'tx-misb-mobile-infantry-strike-base', 'tx-misb-ia-30-infantry-apc', 'aa-50-armored-artillery-troop-carrier');
SELECT 'their 107 locations are in' AS assertion, count(*) AS got, 107 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('xml-280-black-eagle', 'xml-283-wraith', 'xml-285-ghost', 'ngr-standard-deployment-pod', 'xmf-1-drop-fort', 'ngr-undertow-submersible-carrier', 'tx-misb-mobile-infantry-strike-base', 'tx-misb-ia-30-infantry-apc', 'aa-50-armored-artillery-troop-carrier');
SELECT 'their 45 weapon entries are in' AS assertion, count(*) AS got, 45 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('xml-280-black-eagle', 'xml-283-wraith', 'xml-285-ghost', 'ngr-standard-deployment-pod', 'xmf-1-drop-fort', 'ngr-undertow-submersible-carrier', 'tx-misb-mobile-infantry-strike-base', 'tx-misb-ia-30-infantry-apc', 'aa-50-armored-artillery-troop-carrier');

